"""Quaternionic conjugation is a norm-preserving rotation (SO(3) double cover)."""
from __future__ import annotations
import math, random
from typing import List

def quat_mul(p: List[float], q: List[float]) -> List[float]:
    p0, p1, p2, p3 = p; q0, q1, q2, q3 = q
    return [p0*q0 - p1*q1 - p2*q2 - p3*q3,
            p0*q1 + p1*q0 + p2*q3 - p3*q2,
            p0*q2 - p1*q3 + p2*q0 + p3*q1,
            p0*q3 + p1*q2 - p2*q1 + p3*q0]

def quat_norm_sq(q: List[float]) -> float:
    return sum(c * c for c in q)

def quat_inv(q: List[float]) -> List[float]:
    n = quat_norm_sq(q); q0, q1, q2, q3 = q
    return [q0/n, -q1/n, -q2/n, -q3/n]

def conjugate_rotate(q: List[float], x: List[float]) -> List[float]:
    return quat_mul(quat_mul(q, x), quat_inv(q))

def main() -> None:
    rng = random.Random(3)
    for _ in range(5):
        q = [rng.gauss(0, 1) for _ in range(4)]
        x = [0.0] + [rng.gauss(0, 1) for _ in range(3)]  # pure imaginary
        y = conjugate_rotate(q, x)
        print(f"real part of image = {y[0]:+.2e} (should be 0), "
              f"|x|={math.sqrt(quat_norm_sq(x)):.4f} -> |y|={math.sqrt(quat_norm_sq(y)):.4f}")

if __name__ == "__main__":
    main()

"""Balanced Clifford tori: the AM-GM extremum for two and three radii."""
from __future__ import annotations
from typing import Tuple

def two_radius_area_factor(a: float) -> float:
    return 4 * a * (1 - a)            # b = 1 - a, area factor 4ab

def three_radius_volume_factor(a: float, b: float) -> float:
    return a * b * (1 - a - b)        # c = 1 - a - b, volume factor abc

def grid_max_two(steps: int = 100000) -> Tuple[float, float]:
    best_a, best_v = 0.0, 0.0
    for i in range(steps + 1):
        a = i / steps
        v = two_radius_area_factor(a)
        if v > best_v:
            best_a, best_v = a, v
    return best_a, best_v

def grid_max_three(n: int = 300) -> Tuple[float, float, float]:
    best = (0.0, 0.0, 0.0)
    best_v = -1.0
    for i in range(n + 1):
        for j in range(n + 1 - i):
            a, b = i / n, j / n
            v = three_radius_volume_factor(a, b)
            if v > best_v:
                best, best_v = (a, b, 1 - a - b), v
    return best

def main() -> None:
    a, v = grid_max_two()
    print(f"two-radius: argmax a={a:.4f} (exact 1/2), max 4ab={v:.4f} (exact 1)")
    a, b, c = grid_max_three()
    print(f"three-radius: argmax (a,b,c)=({a:.3f},{b:.3f},{c:.3f}) "
          f"(exact 1/3 each), max abc={a*b*c:.6f} (exact 1/27={1/27:.6f})")

if __name__ == "__main__":
    main()

