from __future__ import annotations
from typing import Optional, Tuple

def hopf(z: complex, w: complex) -> Tuple[complex, float]:
    return (2 * z * w.conjugate(), abs(z) ** 2 - abs(w) ** 2)

def recover_hopf_phase(
    z: complex, w: complex, zp: complex, wp: complex, tol: float = 1e-9
) -> Optional[complex]:
    """Given two points of S^3 with equal Hopf image, return the unit scalar
    lambda with (z', w') = (lambda z, lambda w), or None if they are not on the
    same fibre. Uses the division-free Hermitian inner-product witness."""
    # Verify both points lie (approximately) on the unit three-sphere.
    if abs((abs(z) ** 2 + abs(w) ** 2) - 1.0) > tol:
        raise ValueError("(z, w) is not on the unit three-sphere")
    if abs((abs(zp) ** 2 + abs(wp) ** 2) - 1.0) > tol:
        raise ValueError("(z', w') is not on the unit three-sphere")
    # Verify equal Hopf image (same fibre).
    h1, h2 = hopf(z, w), hopf(zp, wp)
    if abs(h1[0] - h2[0]) > tol or abs(h1[1] - h2[1]) > tol:
        return None
    lam = z.conjugate() * zp + w.conjugate() * wp   # the witness
    # Certify: |lambda| = 1 and lambda maps (z, w) to (z', w').
    if abs(abs(lam) - 1.0) > tol:
        return None
    if abs(lam * z - zp) > tol or abs(lam * w - wp) > tol:
        return None
    return lam
